const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Global Carbon Budget 2025";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

// ── Color Palette (Climate-themed) ──
const C = {
  darkBg:    "1B2838",
  darkBg2:   "243447",
  lightBg:   "F0F4F8",
  cardBg:    "FFFFFF",
  teal:      "0891B2",
  tealLight: "22D3EE",
  tealDark:  "065A82",
  coral:     "E8614D",
  coralDark: "C2410C",
  amber:     "F59E0B",
  green:     "10B981",
  darkText:  "1E293B",
  mutedText: "64748B",
  lightText: "CBD5E1",
  white:     "FFFFFF",
  border:    "E2E8F0",
};

// ── Factory functions (never reuse option objects) ──
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1
});

const makeCard = (x, y, w, h) => ({
  x, y, w, h,
  fill: { color: C.cardBg },
  shadow: makeShadow(),
});

// ── Helper: accent bar on left of card ──
const addAccentBar = (slide, x, y, h, color) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color },
    line: { width: 0 },
  });
};

// ── Slide 1: Title Slide ──
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Decorative teal bar at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.8, y: 1.1, w: 8.4, h: 1.0,
    fontSize: 44, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  slide.addText("Who Emits, How Much, and What’s Changing", {
    x: 0.8, y: 2.0, w: 8.4, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: C.tealLight,
    bold: false, align: "left", margin: 0,
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.8, y: 2.9, w: 1.5, h: 0.04,
    fill: { color: C.coral },
  });

  // Subtitle / scope
  slide.addText("Fossil Fuels & Industry  |  1750–2024", {
    x: 0.8, y: 3.2, w: 8.4, h: 0.45,
    fontSize: 16, fontFace: "Calibri", color: C.lightText,
    align: "left", margin: 0,
  });

  // Data source
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.8, y: 3.7, w: 8.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325,
    fill: { color: C.darkBg2 },
  });
  slide.addText("For policy analysts, climate negotiators & sustainability researchers", {
    x: 0.8, y: 5.3, w: 8.4, h: 0.325,
    fontSize: 10, fontFace: "Calibri", color: C.lightText,
    align: "left", valign: "middle", margin: 0,
  });
}

// ── Slide 2: Global Emissions Growth ──
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  // Title
  slide.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", margin: 0,
  });

  // Line chart: emissions over time
  const chartData = [{
    name: "Global CO₂ (Bt/yr)",
    labels: ["1750", "1800", "1850", "1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2020", "2024"],
    values: [0, 0.01, 0.2, 2, 3, 4.5, 6, 9.5, 14, 18, 20.5, 24, 30, 34, 35.2],
  }];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.2, w: 6.2, h: 3.8,
    lineSize: 3,
    lineSmooth: false,
    chartColors: [C.teal],
    showTitle: false,
    showLegend: false,
    catAxisLabelColor: C.mutedText,
    catAxisLabelFontSize: 9,
    catAxisLabelRotation: 45,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 5,
  });

  // Annotation card - right side
  slide.addShape(pres.shapes.RECTANGLE, makeCard(7.0, 1.2, 2.7, 3.8));
  addAccentBar(slide, 7.0, 1.2, 3.8, C.coral);

  slide.addText([
    { text: "Key Inflection Points", options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "Pre-1850", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "Negligible emissions; industrial revolution yet to scale", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "1950", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~6 Bt/yr — post-war industrial boom begins", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "1990", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~20 Bt/yr — nearly 4x in 40 years", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "2024", options: { bold: true, fontSize: 11, color: C.coral, breakLine: true } },
    { text: ">35 Bt/yr — growth slowing but no peak yet", options: { fontSize: 11, color: C.mutedText } },
  ], {
    x: 7.2, y: 1.35, w: 2.35, h: 3.5,
    valign: "top", margin: 0,
  });

  // Footer
  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.2, w: 9.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });
}

// ── Slide 3: Regional Share Shift ──
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.7,
    fontSize: 24, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", margin: 0,
  });

  // Stacked area chart - using stacked bar as approximation
  const chartData = [
    {
      name: "Europe + North America",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [90, 88, 85, 83, 75, 65, 55, 48, 42, 36, 30],
    },
    {
      name: "Asia",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [5, 6, 8, 10, 15, 22, 28, 32, 38, 45, 50],
    },
    {
      name: "Rest of World",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [5, 6, 7, 7, 10, 13, 17, 20, 20, 19, 20],
    },
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 1.15, w: 6.0, h: 3.7,
    barDir: "col",
    barGrouping: "stacked",
    chartColors: [C.tealDark, C.coral, C.amber],
    showTitle: false,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    catAxisLabelColor: C.mutedText,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
  });

  // Insight cards on right
  slide.addShape(pres.shapes.RECTANGLE, makeCard(6.8, 1.15, 2.9, 1.6));
  addAccentBar(slide, 6.8, 1.15, 1.6, C.tealDark);
  slide.addText([
    { text: "1900", options: { bold: true, fontSize: 22, color: C.tealDark, breakLine: true } },
    { text: "Europe + US = >90% of global emissions", options: { fontSize: 12, color: C.darkText, breakLine: true } },
    { text: "Asia = ~5%", options: { fontSize: 12, color: C.mutedText } },
  ], { x: 7.0, y: 1.25, w: 2.5, h: 1.4, valign: "top", margin: 0 });

  slide.addShape(pres.shapes.RECTANGLE, makeCard(6.8, 2.95, 2.9, 1.6));
  addAccentBar(slide, 6.8, 2.95, 1.6, C.coral);
  slide.addText([
    { text: "2024", options: { bold: true, fontSize: 22, color: C.coral, breakLine: true } },
    { text: "Europe + US = <1/3 of global emissions", options: { fontSize: 12, color: C.darkText, breakLine: true } },
    { text: "Asia = ~50%", options: { fontSize: 12, color: C.mutedText } },
  ], { x: 7.0, y: 3.05, w: 2.5, h: 1.4, valign: "top", margin: 0 });

  // Annotation
  slide.addShape(pres.shapes.RECTANGLE, makeCard(6.8, 4.75, 2.9, 0.5));
  slide.addText("Asia’s rise led by China; shift reshapes climate responsibility debates", {
    x: 7.0, y: 4.75, w: 2.5, h: 0.5,
    fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    italic: true, valign: "middle", margin: 0,
  });

  slide.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.5, y: 5.2, w: 9.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });
}

// ── Slide 4: China Dominates Share ──
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  slide.addText("China Now Emits More Than One-Quarter of Global CO₂", {
    x: 0.5, y: 0.3, w: 9.0, h: 0.7,
    fontSize: 26, fontFace: "Georgia", color: C.darkText,
