// ── Color Palette (Climate-themed) ──
const C = {
  darkBg:    "1B2838",
  darkBg2:   "243447",
  lightBg:   "F0F4F8",
  cardBg:    "FFFFFF",
  teal:      "0891B2",
  tealLight: "22D3EE",
  tealDark:  "065A82",
  coral:     "E8614D",
  coralDark: "C2410C",
  amber:     "F59E0B",
  green:     "10B981",
  darkText:  "1E293B",
  mutedText: "64748B",
  lightText: "CBD5E1",
  white:     "FFFFFF",
  border:    "E2E8F0",
};

// ── Factory functions (never reuse option objects) ──
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.1
});

const makeCard = (x, y, w, h) => ({
  x, y, w, h,
  fill: { color: C.cardBg },
  shadow: makeShadow(),
});

// ── Helper: accent bar on left of card ──
const addAccentBar = (slide, x, y, h, color) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color },
    line: { width: 0 },
  });
};

