    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
  });

  // Legend card
  const card1H = 1.2;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, card1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, card1H, C.teal);
  slide.addText([
    { text: "Reading This Chart", options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.teal, breakLine: true } },
    { text: "", options: { fontSize: 3, breakLine: true } },
    { text: "Negative (left) = emissions declined", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "Positive (right) = emissions grew", options: { fontSize: 11, color: C.darkText } },
  ], { x: PANEL_TEXT_X, y: CONTENT_Y + 0.10, w: PANEL_TEXT_W, h: card1H - 0.20, valign: "top", margin: 0 });

  // Declines card
  const card2Y = CONTENT_Y + card1H + CARD_GAP;
  const card2H = 1.0;
  addCard(slide, PANEL_X, card2Y, PANEL_W, card2H);
  addAccentBar(slide, PANEL_X, card2Y, card2H, C.green);
  slide.addText([
    { text: "Declines in 2024", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.green, breakLine: true } },
    { text: "US, EU, UK, Japan — driven by renewables and efficiency", options: { fontSize: 11, color: C.darkText } },
  ], { x: PANEL_TEXT_X, y: card2Y + 0.10, w: PANEL_TEXT_W, h: card2H - 0.20, valign: "top", margin: 0 });

  // Increases card
  const card3Y = card2Y + card2H + CARD_GAP;
  const card3H = 1.0;
  addCard(slide, PANEL_X, card3Y, PANEL_W, card3H);
  addAccentBar(slide, PANEL_X, card3Y, card3H, C.coral);
  slide.addText([
    { text: "Increases in 2024", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.coral, breakLine: true } },
    { text: "Russia, SE Asia, Africa, Central Asia (>10%) — offsetting Western declines", options: { fontSize: 11, color: C.darkText } },
  ], { x: PANEL_TEXT_X, y: card3Y + 0.10, w: PANEL_TEXT_W, h: card3H - 0.20, valign: "top", margin: 0 });

  addSource(slide, "Source: Global Carbon Budget 2025 via Our World in Data  |  Approximate figures for illustrative comparison");
}

// ══════════════════════════════════════════════════
// SLIDE 8: Energy Mix Matters
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US", 22);

  // Bar chart
  const chartData = [{
    name: "Per Capita CO₂ (t/person)",
    labels: ["United States", "EU-27 Average", "United Kingdom"],
    values: [14, 6, 4],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.3, h: 2.6,
    barDir: "bar",
    chartColors: [C.teal],
    showTitle: false,
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 11,
    catAxisLabelColor: C.darkText,
    catAxisLabelFontSize: 11,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    valAxisHidden: true,
  });

  // Explanation card on right
  const cardH = 2.6;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, cardH);
  addAccentBar(slide, PANEL_X, CONTENT_Y, cardH, C.tealDark);
  slide.addText([
    { text: "Same Prosperity, Different Emissions", options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.tealDark, breakLine: true } },
    { text: "", options: { fontSize: 5, breakLine: true } },
    { text: "Among wealthy nations with similar living standards, per capita emissions vary significantly due to energy mix choices:", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
    { text: "Lower emitters", options: { bold: true, fontSize: 11, color: C.green, breakLine: true } },
    { text: "France, UK, Portugal — higher share of nuclear and renewables", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
    { text: "Higher emitters", options: { bold: true, fontSize: 11, color: C.coral, breakLine: true } },
    { text: "Germany, Netherlands, US — more reliant on fossil fuels (coal, gas)", options: { fontSize: 11, color: C.darkText } },
  ], { x: PANEL_TEXT_X, y: CONTENT_Y + 0.10, w: PANEL_TEXT_W, h: cardH - 0.20, valign: "top", margin: 0 });

  // Bottom insight bar
  const barY = CONTENT_Y + cardH + 0.25;
  addCard(slide, MARGIN, barY, SLIDE_W - 2 * MARGIN, 0.65);
  addAccentBar(slide, MARGIN, barY, 0.65, C.amber);
  slide.addText("Energy policy and technology choices can decouple prosperity from emissions — nuclear and renewables offer a proven pathway to lower per capita CO₂.", {
    x: MARGIN + 0.20, y: barY, w: SLIDE_W - 2 * MARGIN - 0.30, h: 0.65,
    fontSize: 12, fontFace: "Calibri", color: C.darkText,
    italic: true, valign: "middle", margin: 0,
  });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 9: Key Takeaways
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: SLIDE_W, h: 0.07,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Key Takeaways: Responsibility Is Shared but Unequal", {
    x: 0.70, y: 0.35, w: 8.6, h: 0.65,
    fontSize: 30, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.70, y: 1.05, w: 1.2, h: 0.04,
    fill: { color: C.coral },
  });

  const takeaways = [
    { num: "1", title: "No Peak Yet", text: "Global emissions exceed 35 Bt/yr and haven’t peaked — growth has slowed but continues", color: C.coral },
    { num: "2", title: "China Leads in Totals", text: "China is the largest annual emitter (~31%) but per capita remains below the US", color: C.teal },
    { num: "3", title: "Historical Responsibility", text: "Europe and the US dominated emissions historically (>90% in 1900) but now account for less than one-third", color: C.tealLight },
    { num: "4", title: "150× Per Capita Gap", text: "Stark inequality persists between richest emitters (US ~14 t) and poorest (Chad ~0.1 t)", color: C.amber },
    { num: "5", title: "Policy Can Decouple", text: "Energy mix choices (nuclear, renewables) can decouple prosperity from emissions — France/UK vs US/Germany", color: C.green },
  ];

  // Grid: 3 on top, 2 on bottom — all left-aligned
  const gridLeft = 0.70;
  const gridW = 2.73;
  const gridH = 1.65;
  const hGap = 0.25;
  const vGap = 0.25;
  const topRowY = 1.35;
  const bottomRowY = topRowY + gridH + vGap;

  // Top row: 3 cards
  for (let i = 0; i < 3; i++) {
    const item = takeaways[i];
    const x = gridLeft + i * (gridW + hGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: topRowY, w: gridW, h: gridH,
      fill: { color: C.darkBgCard },
      shadow: makeShadow(),
    });
    addAccentBar(slide, x, topRowY, gridH, item.color);

    slide.addText([
      { text: item.num, options: { bold: true, fontSize: 26, color: item.color, breakLine: true } },
      { text: item.title, options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.white, breakLine: true } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: item.text, options: { fontSize: 11, color: C.lightText } },
    ], { x: x + 0.15, y: topRowY + 0.12, w: gridW - 0.30, h: gridH - 0.24, valign: "top", margin: 0 });
  }

  // Bottom row: 2 cards, left-aligned with top row
  for (let i = 0; i < 2; i++) {
    const item = takeaways[3 + i];
    const x = gridLeft + i * (gridW + hGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: bottomRowY, w: gridW, h: gridH,
      fill: { color: C.darkBgCard },
      shadow: makeShadow(),
    });
    addAccentBar(slide, x, bottomRowY, gridH, item.color);

    slide.addText([
      { text: item.num, options: { bold: true, fontSize: 26, color: item.color, breakLine: true } },
      { text: item.title, options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.white, breakLine: true } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: item.text, options: { fontSize: 11, color: C.lightText } },
    ], { x: x + 0.15, y: bottomRowY + 0.12, w: gridW - 0.30, h: gridH - 0.24, valign: "top", margin: 0 });
  }

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.85, w: SLIDE_W, h: 0.30,
    fill: { color: C.darkBg2 },
  });
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.70, y: 4.85, w: 8.6, h: 0.30,
    fontSize: 10, fontFace: "Calibri", color: C.lightText,
    align: "left", valign: "middle", margin: 0,
  });
}

// ── Write ──
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("SUCCESS: /app/output/final_deck.pptx created"))
  .catch(err => console.error("ERROR:", err));

