const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Global Carbon Budget 2025";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

// ── Color Palette ──
const C = {
  darkBg:     "1B2838",
  darkBgCard: "2A3F55",  // lighter than bg for contrast on dark slides
  darkBg2:    "243447",
  lightBg:    "F0F4F8",
  cardBg:     "FFFFFF",
  teal:       "0891B2",
  tealLight:  "22D3EE",
  tealDark:   "065A82",
  coral:      "E8614D",
  coralDark:  "C2410C",
  amber:      "F59E0B",
  green:      "10B981",
  darkText:   "1E293B",
  mutedText:  "64748B",
  lightText:  "CBD5E1",
  white:      "FFFFFF",
  border:     "E2E8F0",
};

// ── Layout Constants ──
const SLIDE_W = 10;
const SLIDE_H = 5.625;
const MARGIN = 0.50;          // min margin on all sides
const RIGHT_EDGE = SLIDE_W - MARGIN;   // 9.50
const BOTTOM_EDGE = SLIDE_H - MARGIN;  // 5.125
const TITLE_Y = 0.30;
const TITLE_H = 0.80;         // room for 2-line wrap
const CONTENT_Y = 1.20;
const SOURCE_Y = 4.90;        // above bottom margin
const SOURCE_H = 0.22;

// Right panel layout
const PANEL_X = 6.50;
const PANEL_W = RIGHT_EDGE - PANEL_X; // 3.0
const PANEL_TEXT_PAD = 0.20;
const PANEL_TEXT_X = PANEL_X + PANEL_TEXT_PAD;
const PANEL_TEXT_W = PANEL_W - 2 * PANEL_TEXT_PAD; // 2.6
const CARD_GAP = 0.25;

// ── Factory functions ──
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10
});

const addSource = (slide, text) => {
  slide.addText(text || "Source: Global Carbon Budget 2025 via Our World in Data", {
    x: MARGIN, y: SOURCE_Y, w: SLIDE_W - 2 * MARGIN, h: SOURCE_H,
    fontSize: 9, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });
};

const addTitle = (slide, text, fontSize = 26) => {
  slide.addText(text, {
    x: MARGIN, y: TITLE_Y, w: SLIDE_W - 2 * MARGIN, h: TITLE_H,
    fontSize, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", margin: 0,
  });
};

const addCard = (slide, x, y, w, h) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });
};

const addAccentBar = (slide, x, y, h, color) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.07, h,
    fill: { color },
    line: { width: 0 },
  });
};

// ══════════════════════════════════════════════════
// SLIDE 1: Title
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: SLIDE_W, h: 0.07,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.80, y: 1.0, w: 8.4, h: 0.9,
    fontSize: 44, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  slide.addText("Who Emits, How Much, and What’s Changing", {
    x: 0.80, y: 1.9, w: 8.4, h: 0.7,
    fontSize: 28, fontFace: "Georgia", color: C.tealLight,
    bold: false, align: "left", margin: 0,
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.80, y: 2.8, w: 1.5, h: 0.04,
    fill: { color: C.coral },
  });

  // Scope
  slide.addText("Fossil Fuels & Industry  |  1750–2024", {
    x: 0.80, y: 3.1, w: 8.4, h: 0.4,
    fontSize: 16, fontFace: "Calibri", color: C.lightText,
    align: "left", margin: 0,
  });

  // Data source
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.80, y: 3.6, w: 8.4, h: 0.35,
    fontSize: 12, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });

  // Footer bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.85, w: SLIDE_W, h: 0.30,
    fill: { color: C.darkBg2 },
  });
  slide.addText("For policy analysts, climate negotiators & sustainability researchers", {
    x: 0.80, y: 4.85, w: 8.4, h: 0.30,
    fontSize: 10, fontFace: "Calibri", color: C.lightText,
    align: "left", valign: "middle", margin: 0,
  });
}

// ══════════════════════════════════════════════════
// SLIDE 2: Global Emissions Growth
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today");

  // Line chart
  const chartData = [{
    name: "Global CO₂ (Bt/yr)",
    labels: ["1750", "1800", "1850", "1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2020", "2024"],
    values: [0, 0.01, 0.2, 2, 3, 4.5, 6, 9.5, 14, 18, 20.5, 24, 30, 34, 35.2],
  }];

  slide.addChart(pres.charts.LINE, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.8, h: 3.4,
    lineSize: 3,
    lineSmooth: false,
    chartColors: [C.teal],
    showTitle: false,
    showLegend: false,
    catAxisLabelColor: C.mutedText,
    catAxisLabelFontSize: 9,
    catAxisLabelRotation: 45,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 5,
  });

  // Right panel: inflection points card
  const cardH = 3.4;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, cardH);
  addAccentBar(slide, PANEL_X, CONTENT_Y, cardH, C.coral);

  slide.addText([
    { text: "Key Inflection Points", options: { bold: true, fontSize: 14, fontFace: "Georgia", color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "Pre-1850", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "Negligible emissions; industrial revolution yet to scale", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "1950", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~6 Bt/yr — post-war industrial boom begins", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "1990", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~20 Bt/yr — nearly 4× in 40 years", options: { fontSize: 11, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 6, breakLine: true } },
    { text: "2024", options: { bold: true, fontSize: 11, color: C.coral, breakLine: true } },
    { text: ">35 Bt/yr — growth slowing but no peak yet", options: { fontSize: 11, color: C.mutedText } },
  ], {
    x: PANEL_TEXT_X, y: CONTENT_Y + 0.12, w: PANEL_TEXT_W, h: cardH - 0.24,
    valign: "top", margin: 0,
  });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 3: Regional Share Shift
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", 24);

  // Stacked bar chart
  const chartData = [
    {
      name: "Europe + North America",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [90, 88, 85, 83, 75, 65, 55, 48, 42, 36, 30],
    },
    {
      name: "Asia",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [5, 6, 8, 10, 15, 22, 28, 32, 38, 45, 50],
    },
    {
      name: "Rest of World",
      labels: ["1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2024"],
      values: [5, 6, 7, 7, 10, 13, 17, 20, 20, 19, 20],
    },
  ];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.4,
    barDir: "col",
    barGrouping: "stacked",
    chartColors: [C.tealDark, C.coral, C.amber],
    showTitle: false,
    showLegend: true,
    legendPos: "b",
    legendFontSize: 9,
    catAxisLabelColor: C.mutedText,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
  });

  // 1900 card
  const card1H = 1.3;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, card1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, card1H, C.tealDark);
  slide.addText([
    { text: "1900", options: { bold: true, fontSize: 20, color: C.tealDark, breakLine: true } },
    { text: "Europe + US = >90%", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "Asia = ~5%", options: { fontSize: 11, color: C.mutedText } },
  ], { x: PANEL_TEXT_X, y: CONTENT_Y + 0.10, w: PANEL_TEXT_W, h: card1H - 0.20, valign: "top", margin: 0 });

  // 2024 card
  const card2Y = CONTENT_Y + card1H + CARD_GAP;
  const card2H = 1.3;
  addCard(slide, PANEL_X, card2Y, PANEL_W, card2H);
  addAccentBar(slide, PANEL_X, card2Y, card2H, C.coral);
  slide.addText([
    { text: "2024", options: { bold: true, fontSize: 20, color: C.coral, breakLine: true } },
    { text: "Europe + US = <1/3", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "Asia = ~50%", options: { fontSize: 11, color: C.mutedText } },
  ], { x: PANEL_TEXT_X, y: card2Y + 0.10, w: PANEL_TEXT_W, h: card2H - 0.20, valign: "top", margin: 0 });

  // Insight note
  const noteY = card2Y + card2H + CARD_GAP;
  slide.addText("Asia’s rise led by China; shift reshapes climate responsibility debates", {
    x: PANEL_X, y: noteY, w: PANEL_W, h: 0.40,
    fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    italic: true, valign: "top", margin: 0,
  });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 4: China Dominates Share
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "China Now Emits More Than One-Quarter of Global CO₂");

  // Horizontal bar chart
  const chartData = [{
    name: "Share of Global CO₂ (2024)",
    labels: ["China", "United States", "India", "EU-27", "Russia", "Africa", "S. America", "Int’l Transport"],
    values: [31, 13, 8, 6, 5, 3.5, 3.5, 3],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.5,
    barDir: "bar",
    chartColors: [C.coral],
    showTitle: false,
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 10,
    catAxisLabelColor: C.darkText,
    catAxisLabelFontSize: 10,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    valAxisHidden: true,
  });

  // China insight card
  const card1H = 1.6;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, card1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, card1H, C.coral);
  slide.addText([
    { text: "China: 31%", options: { bold: true, fontSize: 20, color: C.coral, breakLine: true } },
    { text: "of global CO₂ emissions", options: { fontSize: 12, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
