const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Global Carbon Budget 2025";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

// ── Color Palette ──
const C = {
  darkBg:     "1B2838",
  darkBgCard: "2A3F55",
  darkBg2:    "1F3044",
  lightBg:    "F0F4F8",
  cardBg:     "FFFFFF",
  teal:       "0891B2",
  tealLight:  "22D3EE",
  tealDark:   "065A82",
  coral:      "E8614D",
  coralDark:  "C2410C",
  amber:      "F59E0B",
  green:      "10B981",
  darkText:   "1E293B",
  bodyText:   "334155",
  mutedText:  "475569",   // darker for WCAG AA on light bg
  srcDark:    "94A3B8",   // for dark bg footers
  lightText:  "CBD5E1",
  white:      "FFFFFF",
  border:     "E2E8F0",
};

// ── Layout Constants ──
const SLIDE_W = 10;
const SLIDE_H = 5.625;
const MARGIN = 0.50;
const RIGHT_EDGE = SLIDE_W - MARGIN;   // 9.50
const TITLE_Y = 0.50;
const TITLE_H = 0.75;
const TITLE_FS = 22;          // consistent across all content slides
const CONTENT_Y = 1.40;       // after title + gap
const SOURCE_Y = 4.92;

// Right panel
const PANEL_X = 6.50;
const PANEL_W = RIGHT_EDGE - PANEL_X; // 3.0
const PTEXT_X = PANEL_X + 0.18;
const PTEXT_W = PANEL_W - 0.36;       // 2.64
const CARD_GAP = 0.28;
const CARD_PAD = 0.12;

// ── Helpers ──
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10
});

const addSource = (slide, text) => {
  slide.addText(text || "Source: Global Carbon Budget 2025 via Our World in Data", {
    x: MARGIN, y: SOURCE_Y, w: SLIDE_W - 2 * MARGIN, h: 0.20,
    fontSize: 9, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });
};

const addTitle = (slide, text) => {
  slide.addText(text, {
    x: MARGIN, y: TITLE_Y, w: SLIDE_W - 2 * MARGIN, h: TITLE_H,
    fontSize: TITLE_FS, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", margin: 0,
  });
};

const addCard = (slide, x, y, w, h) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });
};

const addAccentBar = (slide, x, y, h, color) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.07, h,
    fill: { color },
    line: { width: 0 },
  });
};

// ══════════════════════════════════════════════════
// SLIDE 1: Title
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: SLIDE_W, h: 0.07,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.80, y: 1.0, w: 8.4, h: 0.85,
    fontSize: 44, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  slide.addText("Who Emits, How Much, and What's Changing", {
    x: 0.80, y: 1.85, w: 8.4, h: 0.65,
    fontSize: 28, fontFace: "Georgia", color: C.tealLight,
    bold: false, align: "left", margin: 0,
  });

  // Scope
  slide.addText("Fossil Fuels & Industry  |  1750–2024", {
    x: 0.80, y: 2.85, w: 8.4, h: 0.35,
    fontSize: 16, fontFace: "Calibri", color: C.lightText,
    align: "left", margin: 0,
  });

