  darkBg:     "1B2838",
  darkBgCard: "2A3F55",
  darkBg2:    "1F3044",
  lightBg:    "F0F4F8",
  cardBg:     "FFFFFF",
  teal:       "0891B2",
  tealLight:  "22D3EE",
  tealDark:   "065A82",
  coral:      "E8614D",
