    { text: "between lowest and highest emitters", options: { fontSize: 11, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 3, breakLine: true } },
    { text: "An American emits in 2 days what a person in Chad emits in a year", options: { fontSize: 10, color: C.mutedText, italic: true } },
  ], { x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: c1H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // Context card — reduced content to fit
  const c2Y = CONTENT_Y + c1H + CARD_GAP;
  const c2H = 1.50;
  addCard(slide, PANEL_X, c2Y, PANEL_W, c2H);
  addAccentBar(slide, PANEL_X, c2Y, c2H, C.tealDark);
  slide.addText([
    { text: "Key Context", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.tealDark, breakLine: true } },
    { text: "", options: { fontSize: 3, breakLine: true } },
    { text: "Oil producers (Qatar, UAE) have even higher per capita rates", options: { bullet: true, fontSize: 10, color: C.darkText, breakLine: true } },
    { text: "US/Canada/Australia: ~3× global average", options: { bullet: true, fontSize: 10, color: C.darkText, breakLine: true } },
    { text: "France/UK lower than US at similar living standards", options: { bullet: true, fontSize: 10, color: C.mutedText } },
  ], { x: PTEXT_X, y: c2Y + CARD_PAD, w: PTEXT_W, h: c2H - 2 * CARD_PAD, valign: "top", margin: 0 });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 6: Per Capita Snapshot
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India");

  const chartData = [{
    name: "Per Capita CO₂ (t/person)",
    labels: ["United States", "Canada", "China", "South Africa", "EU-27", "World Avg", "UK", "India", "Kenya"],
    values: [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.3,
    barDir: "bar",
    chartColors: [C.teal],
    showTitle: false, showLegend: false,
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: C.darkText, dataLabelFontSize: 10,
    catAxisLabelColor: C.darkText, catAxisLabelFontSize: 10,
    valAxisLabelColor: C.mutedText, valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    valAxisHidden: true,
  });

  // China vs US
  const c1H = 1.15;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, c1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, c1H, C.coral);
  slide.addText([
    { text: "China vs. US", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.coral, breakLine: true } },
    { text: "Largest total emitter, but per capita (~9 t) well below the US (~14 t)", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: c1H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // India card
  const c2Y = CONTENT_Y + c1H + CARD_GAP;
  const c2H = 1.15;
  addCard(slide, PANEL_X, c2Y, PANEL_W, c2H);
  addAccentBar(slide, PANEL_X, c2Y, c2H, C.teal);
  slide.addText([
    { text: "India's Low Baseline", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.teal, breakLine: true } },
    { text: "~2 t/person — far below the world average of ~4.5 t", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: c2Y + CARD_PAD, w: PTEXT_W, h: c2H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // World avg
  const c3Y = c2Y + c2H + CARD_GAP;
  addCard(slide, PANEL_X, c3Y, PANEL_W, 0.55);
  addAccentBar(slide, PANEL_X, c3Y, 0.55, C.amber);
  slide.addText([
    { text: "World Avg: 4.5 t/person", options: { bold: true, fontSize: 11, color: C.amber, breakLine: true } },
    { text: "Half the listed countries fall below this line", options: { fontSize: 10, color: C.mutedText } },
  ], { x: PTEXT_X, y: c3Y + 0.06, w: PTEXT_W, h: 0.43, valign: "top", margin: 0 });

  addSource(slide, "Source: Global Carbon Budget 2025 via Our World in Data  |  Ref: figure_8.jpg");
}

// ══════════════════════════════════════════════════
// SLIDE 7: 2024 Annual Change
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew");

  const chartData = [{
    name: "Emissions Change 2024 (%)",
    labels: ["EU-27", "UK", "United States", "Japan", "India", "SE Asia", "Russia", "Central Asia"],
    values: [-3.5, -4.0, -1.5, -2.0, 5.0, 4.0, 2.5, 10.0],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.3,
    barDir: "bar",
    chartColors: [C.teal],
    showTitle: false, showLegend: false,
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: C.darkText, dataLabelFontSize: 10,
    catAxisLabelColor: C.darkText, catAxisLabelFontSize: 10,
    valAxisLabelColor: C.mutedText, valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
  });

  // Legend card
  const c1H = 1.10;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, c1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, c1H, C.teal);
  slide.addText([
    { text: "Reading This Chart", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.teal, breakLine: true } },
    { text: "", options: { fontSize: 2, breakLine: true } },
    { text: "Negative (left) = emissions declined", options: { fontSize: 10, color: C.darkText, breakLine: true } },
    { text: "Positive (right) = emissions grew", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: c1H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // Declines card
  const c2Y = CONTENT_Y + c1H + CARD_GAP;
  const c2H = 0.95;
  addCard(slide, PANEL_X, c2Y, PANEL_W, c2H);
  addAccentBar(slide, PANEL_X, c2Y, c2H, C.green);
  slide.addText([
    { text: "Declines in 2024", options: { bold: true, fontSize: 12, fontFace: "Georgia", color: C.green, breakLine: true } },
    { text: "US, EU, UK, Japan — renewables & efficiency", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: c2Y + CARD_PAD, w: PTEXT_W, h: c2H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // Increases card
  const c3Y = c2Y + c2H + CARD_GAP;
  const c3H = 0.95;
  addCard(slide, PANEL_X, c3Y, PANEL_W, c3H);
  addAccentBar(slide, PANEL_X, c3Y, c3H, C.coral);
  slide.addText([
    { text: "Increases in 2024", options: { bold: true, fontSize: 12, fontFace: "Georgia", color: C.coral, breakLine: true } },
    { text: "Russia, SE Asia, Africa, Central Asia (>10%)", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: c3Y + CARD_PAD, w: PTEXT_W, h: c3H - 2 * CARD_PAD, valign: "top", margin: 0 });

  addSource(slide, "Source: Global Carbon Budget 2025 via Our World in Data  |  Approximate figures for illustrative comparison");
}

// ══════════════════════════════════════════════════
// SLIDE 8: Energy Mix Matters
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US");

  // Bar chart
  const chartData = [{
    name: "Per Capita CO₂ (t/person)",
    labels: ["United States", "EU-27 Average", "United Kingdom"],
    values: [14, 6, 4],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.3, h: 2.4,
    barDir: "bar",
    chartColors: [C.teal],
    showTitle: false, showLegend: false,
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: C.darkText, dataLabelFontSize: 11,
    catAxisLabelColor: C.darkText, catAxisLabelFontSize: 11,
    valAxisLabelColor: C.mutedText, valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    valAxisHidden: true,
  });

  // Explanation card
  const cardH = 2.4;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, cardH);
  addAccentBar(slide, PANEL_X, CONTENT_Y, cardH, C.tealDark);
  slide.addText([
    { text: "Same Prosperity, Different Emissions", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.tealDark, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
    { text: "Among wealthy nations, per capita emissions vary significantly due to energy mix:", options: { fontSize: 10, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
    { text: "Lower emitters", options: { bold: true, fontSize: 10, color: C.green, breakLine: true } },
    { text: "France, UK, Portugal — nuclear & renewables", options: { fontSize: 10, color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 4, breakLine: true } },
    { text: "Higher emitters", options: { bold: true, fontSize: 10, color: C.coral, breakLine: true } },
    { text: "Germany, Netherlands, US — coal & gas", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: cardH - 2 * CARD_PAD, valign: "top", margin: 0 });

  // Bottom insight bar
  const barY = CONTENT_Y + cardH + 0.30;
  addCard(slide, MARGIN, barY, SLIDE_W - 2 * MARGIN, 0.60);
  addAccentBar(slide, MARGIN, barY, 0.60, C.amber);
  slide.addText("Energy policy and technology choices can decouple prosperity from emissions — nuclear and renewables offer a proven pathway.", {
    x: MARGIN + 0.20, y: barY, w: SLIDE_W - 2 * MARGIN - 0.35, h: 0.60,
    fontSize: 11, fontFace: "Calibri", color: C.darkText,
    italic: true, valign: "middle", margin: 0,
  });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 9: Key Takeaways
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: SLIDE_W, h: 0.07,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Key Takeaways: Responsibility Is Shared but Unequal", {
    x: 0.70, y: 0.40, w: 8.6, h: 0.60,
    fontSize: 28, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  const takeaways = [
    { num: "1", title: "No Peak Yet", text: "Global emissions exceed 35 Bt/yr and haven't peaked — growth has slowed but continues", color: C.coral },
    { num: "2", title: "China Leads in Totals", text: "China is the largest annual emitter (~31%) but per capita remains below the US", color: C.teal },
    { num: "3", title: "Historical Responsibility", text: "Europe and the US dominated emissions historically (>90% in 1900) but now <1/3", color: C.tealLight },
    { num: "4", title: "150× Per Capita Gap", text: "Stark inequality: US ~14 t vs. Chad ~0.1 t per person per year", color: C.amber },
    { num: "5", title: "Policy Can Decouple", text: "Energy mix choices (nuclear, renewables) decouple prosperity from emissions", color: C.green },
  ];

  // Grid: 3 on top, 2 on bottom — all left-aligned with same grid
  const gridLeft = 0.70;
  const gridW = 2.73;
  const gridH = 1.55;
  const hGap = 0.25;
  const vGap = 0.25;
  const topRowY = 1.20;

  for (let i = 0; i < 3; i++) {
    const item = takeaways[i];
    const x = gridLeft + i * (gridW + hGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: topRowY, w: gridW, h: gridH,
      fill: { color: C.darkBgCard },
      shadow: makeShadow(),
    });
    addAccentBar(slide, x, topRowY, gridH, item.color);

    slide.addText([
      { text: item.num, options: { bold: true, fontSize: 24, color: item.color, breakLine: true } },
      { text: item.title, options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.white, breakLine: true } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: item.text, options: { fontSize: 10, color: C.lightText } },
    ], { x: x + 0.15, y: topRowY + 0.10, w: gridW - 0.30, h: gridH - 0.20, valign: "top", margin: 0 });
  }

  // Bottom row: left-aligned with top row
  const bottomRowY = topRowY + gridH + vGap;
  for (let i = 0; i < 2; i++) {
    const item = takeaways[3 + i];
    const x = gridLeft + i * (gridW + hGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: bottomRowY, w: gridW, h: gridH,
      fill: { color: C.darkBgCard },
      shadow: makeShadow(),
    });
    addAccentBar(slide, x, bottomRowY, gridH, item.color);

    slide.addText([
      { text: item.num, options: { bold: true, fontSize: 24, color: item.color, breakLine: true } },
      { text: item.title, options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.white, breakLine: true } },
      { text: "", options: { fontSize: 4, breakLine: true } },
      { text: item.text, options: { fontSize: 10, color: C.lightText } },
    ], { x: x + 0.15, y: bottomRowY + 0.10, w: gridW - 0.30, h: gridH - 0.20, valign: "top", margin: 0 });
  }

  // Footer
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.85, w: SLIDE_W, h: 0.28,
    fill: { color: C.darkBg2 },
  });
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.70, y: 4.85, w: 8.6, h: 0.28,
    fontSize: 10, fontFace: "Calibri", color: C.lightText,
    align: "left", valign: "middle", margin: 0,
  });
}

// ── Write ──
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("SUCCESS: /app/output/final_deck.pptx created"))
  .catch(err => console.error("ERROR:", err));

