const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Global Carbon Budget 2025";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

// ── Color Palette ──
const C = {
  darkBg:     "1B2838",
  darkBgCard: "2A3F55",
  darkBg2:    "1F3044",
  lightBg:    "F0F4F8",
  cardBg:     "FFFFFF",
  teal:       "0891B2",
  tealLight:  "22D3EE",
  tealDark:   "065A82",
  coral:      "E8614D",
  coralDark:  "C2410C",
  amber:      "F59E0B",
  green:      "10B981",
  darkText:   "1E293B",
  bodyText:   "334155",
  mutedText:  "475569",   // darker for WCAG AA on light bg
  srcDark:    "94A3B8",   // for dark bg footers
  lightText:  "CBD5E1",
  white:      "FFFFFF",
  border:     "E2E8F0",
};

// ── Layout Constants ──
const SLIDE_W = 10;
const SLIDE_H = 5.625;
const MARGIN = 0.50;
const RIGHT_EDGE = SLIDE_W - MARGIN;   // 9.50
const TITLE_Y = 0.50;
const TITLE_H = 0.75;
const TITLE_FS = 22;          // consistent across all content slides
const CONTENT_Y = 1.40;       // after title + gap
const SOURCE_Y = 4.92;

// Right panel
const PANEL_X = 6.50;
const PANEL_W = RIGHT_EDGE - PANEL_X; // 3.0
const PTEXT_X = PANEL_X + 0.18;
const PTEXT_W = PANEL_W - 0.36;       // 2.64
const CARD_GAP = 0.28;
const CARD_PAD = 0.12;

// ── Helpers ──
const makeShadow = () => ({
  type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.10
});

const addSource = (slide, text) => {
  slide.addText(text || "Source: Global Carbon Budget 2025 via Our World in Data", {
    x: MARGIN, y: SOURCE_Y, w: SLIDE_W - 2 * MARGIN, h: 0.20,
    fontSize: 9, fontFace: "Calibri", color: C.mutedText,
    align: "left", margin: 0,
  });
};

const addTitle = (slide, text) => {
  slide.addText(text, {
    x: MARGIN, y: TITLE_Y, w: SLIDE_W - 2 * MARGIN, h: TITLE_H,
    fontSize: TITLE_FS, fontFace: "Georgia", color: C.darkText,
    bold: true, align: "left", margin: 0,
  });
};

const addCard = (slide, x, y, w, h) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w, h,
    fill: { color: C.cardBg },
    shadow: makeShadow(),
  });
};

const addAccentBar = (slide, x, y, h, color) => {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.07, h,
    fill: { color },
    line: { width: 0 },
  });
};

// ══════════════════════════════════════════════════
// SLIDE 1: Title
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.darkBg };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: SLIDE_W, h: 0.07,
    fill: { color: C.teal },
  });

  // Title
  slide.addText("Global CO₂ Emissions", {
    x: 0.80, y: 1.0, w: 8.4, h: 0.85,
    fontSize: 44, fontFace: "Georgia", color: C.white,
    bold: true, align: "left", margin: 0,
  });

  slide.addText("Who Emits, How Much, and What's Changing", {
    x: 0.80, y: 1.85, w: 8.4, h: 0.65,
    fontSize: 28, fontFace: "Georgia", color: C.tealLight,
    bold: false, align: "left", margin: 0,
  });

  // Scope
  slide.addText("Fossil Fuels & Industry  |  1750–2024", {
    x: 0.80, y: 2.85, w: 8.4, h: 0.35,
    fontSize: 16, fontFace: "Calibri", color: C.lightText,
    align: "left", margin: 0,
  });

  // Data source
  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
    x: 0.80, y: 3.30, w: 8.4, h: 0.30,
    fontSize: 12, fontFace: "Calibri", color: C.srcDark,
    align: "left", margin: 0,
  });

  // Footer bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 4.85, w: SLIDE_W, h: 0.28,
    fill: { color: C.darkBg2 },
  });
  slide.addText("For policy analysts, climate negotiators & sustainability researchers", {
    x: 0.80, y: 4.85, w: 8.4, h: 0.28,
    fontSize: 10, fontFace: "Calibri", color: C.lightText,
    align: "left", valign: "middle", margin: 0,
  });
}

// ══════════════════════════════════════════════════
// SLIDE 2: Global Emissions Growth
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

  addTitle(slide, "Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today");

  // Line chart
  const chartData = [{
    name: "Global CO₂ (Bt/yr)",
    labels: ["1750", "1800", "1850", "1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2020", "2024"],
    values: [0, 0.01, 0.2, 2, 3, 4.5, 6, 9.5, 14, 18, 20.5, 24, 30, 34, 35.2],
  }];

  slide.addChart(pres.charts.LINE, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.3,
    lineSize: 3, lineSmooth: false,
    chartColors: [C.teal],
    showTitle: false, showLegend: false,
    catAxisLabelColor: C.mutedText, catAxisLabelFontSize: 9, catAxisLabelRotation: 45,
    valAxisLabelColor: C.mutedText, valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    showValue: false,
    lineDataSymbol: "circle", lineDataSymbolSize: 5,
  });

  // Inflection points card
  const cardH = 3.3;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, cardH);
  addAccentBar(slide, PANEL_X, CONTENT_Y, cardH, C.coral);

  slide.addText([
    { text: "Key Inflection Points", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.darkText, breakLine: true } },
    { text: "", options: { fontSize: 5, breakLine: true } },
    { text: "Pre-1850", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "Negligible emissions", options: { fontSize: 10, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 5, breakLine: true } },
    { text: "1950", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~6 Bt/yr — post-war boom", options: { fontSize: 10, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 5, breakLine: true } },
    { text: "1990", options: { bold: true, fontSize: 11, color: C.teal, breakLine: true } },
    { text: "~20 Bt/yr — 4× in 40 yrs", options: { fontSize: 10, color: C.mutedText, breakLine: true } },
    { text: "", options: { fontSize: 5, breakLine: true } },
    { text: "2024", options: { bold: true, fontSize: 11, color: C.coral, breakLine: true } },
    { text: ">35 Bt/yr — no peak yet", options: { fontSize: 10, color: C.mutedText } },
  ], {
    x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: cardH - 2 * CARD_PAD,
    valign: "top", margin: 0,
  });

  addSource(slide);
}

// ══════════════════════════════════════════════════
// SLIDE 3: Regional Share Shift
// ══════════════════════════════════════════════════
{
  const slide = pres.addSlide();
  slide.background = { color: C.lightBg };

