file.content:
  addTitle(slide, "Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India");

  const chartData = [{
    name: "Per Capita CO₂ (t/person)",
    labels: ["United States", "Canada", "China", "South Africa", "EU-27", "World Avg", "UK", "India", "Kenya"],
    values: [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4],
  }];

  slide.addChart(pres.charts.BAR, chartData, {
    x: MARGIN, y: CONTENT_Y, w: 5.7, h: 3.3,
    barDir: "bar",
    chartColors: [C.teal],
    showTitle: false, showLegend: false,
    showValue: true, dataLabelPosition: "outEnd", dataLabelColor: C.darkText, dataLabelFontSize: 10,
    catAxisLabelColor: C.darkText, catAxisLabelFontSize: 10,
    valAxisLabelColor: C.mutedText, valAxisLabelFontSize: 9,
    valGridLine: { color: C.border, size: 0.5 },
    catGridLine: { style: "none" },
    valAxisHidden: true,
  });

  // China vs US
  const c1H = 1.15;
  addCard(slide, PANEL_X, CONTENT_Y, PANEL_W, c1H);
  addAccentBar(slide, PANEL_X, CONTENT_Y, c1H, C.coral);
  slide.addText([
    { text: "China vs. US", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.coral, breakLine: true } },
    { text: "Largest total emitter, but per capita (~9 t) well below the US (~14 t)", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: CONTENT_Y + CARD_PAD, w: PTEXT_W, h: c1H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // India card
  const c2Y = CONTENT_Y + c1H + CARD_GAP;
  const c2H = 1.15;
  addCard(slide, PANEL_X, c2Y, PANEL_W, c2H);
  addAccentBar(slide, PANEL_X, c2Y, c2H, C.teal);
  slide.addText([
    { text: "India's Low Baseline", options: { bold: true, fontSize: 13, fontFace: "Georgia", color: C.teal, breakLine: true } },
    { text: "~2 t/person — far below the world average of ~4.5 t", options: { fontSize: 10, color: C.darkText } },
  ], { x: PTEXT_X, y: c2Y + CARD_PAD, w: PTEXT_W, h: c2H - 2 * CARD_PAD, valign: "top", margin: 0 });

  // World avg
  const c3Y = c2Y + c2H + CARD_GAP;
  addCard(slide, PANEL_X, c3Y, PANEL_W, 0.55);
  addAccentBar(slide, PANEL_X, c3Y, 0.55, C.amber);
  slide.addText([
    { text: "World Avg: 4.5 t/person", options: { bold: true, fontSize: 11, color: C.amber, breakLine: true } },
    { text: "Half the listed countries fall below this line", options: { fontSize: 10, color: C.mutedText } },
  ], { x: PTEXT_X, y: c3Y + 0.06, w: PTEXT_W, h: 0.43, valign: "top", margin: 0 });

  addSource(slide, "Source: Global Carbon Budget 2025 via Our World in Data  |  Ref: figure_8.jpg");
}

